plantuml:
@startuml
title Integrated communication activity for choosing communication mode, optionally encrypting, sending unicast/multicast/broadcast messages, receiving and decrypting, and joining/leaving multicast groups.

|Agent|
start

:Choose communication type;
if (Communication type?) then (unicast / multicast / broadcast)
:Choose encryption;
if (Encrypt?) then (encrypted)
|Encryption/Decryption|
:Encrypt message;
if (Encrypt message) then (unicast)
(A)
detach
elseif (Encrypt message) then (multicast)
|Sending Agent|
:Send multicast;
else (broadcast)
:Send broadcast;
endif
(B)
|Receiving Agent|
:Receive message;
if (Receive message) then (encrypted)
|Encryption/Decryption|
:Decrypt message;
stop
else (not encrypted)
stop
endif
else (not encrypted)
endif
(A)
|Sending Agent|
:Send unicast;
(B)
detach
else (join / leave)
|Agent|
:Join multicast group;
stop
endif

@enduml
